// 布隆过滤器：从 EasyList + EasyPrivacy 提取的 101127 个广告/追踪域名
// 误判率: 0.1%, 位数组大小: 1453963 bits (177 KB), 哈希函数数: 10
// 哈希算法: FNV-1a + MurmurHash (double-hashing)

const BLOOM_M = 1453963;
const BLOOM_K = 10;
const BLOOM_DATA = "";

// FNV-1a 哈希 (32-bit)
function fnv1a32(s: string): number {
  let h = 0x811c9dc5 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// 简单 Murmur-like 哈希 (32-bit)
function murmur32(s: string): number {
  let h = 0 >>> 0;
  const data = s;
  let i = 0;
  for (i = 0; i < data.length; i++) {
    let k = data.charCodeAt(i) | 0;
    k = Math.imul(k, 0x5bd1e995) | 0;
    k = (k ^ (k >>> 24)) | 0;
    k = Math.imul(k, 0x5bd1e995) | 0;
    h = Math.imul(h, 0x5bd1e995) ^ k;
  }
  h ^= data.length;
  h ^= h >>> 13;
  h = Math.imul(h, 0x5bd1e995) | 0;
  h ^= h >>> 15;
  return h >>> 0;
}

// 解码 bloom filter 位数组
let _bloomBytes: Uint8Array | null = null;
function bloomBytes(): Uint8Array {
  if (_bloomBytes !== null) return _bloomBytes;
  const binary = atob(BLOOM_DATA);
  _bloomBytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) _bloomBytes[i] = binary.charCodeAt(i);
  return _bloomBytes;
}

// 检查域名是否在布隆过滤器中
function bloomCheck(domain: string): boolean {
  const bytes = bloomBytes();
  const h1 = fnv1a32(domain);
  const h2 = murmur32(domain);
  for (let i = 0; i < BLOOM_K; i++) {
    const bitPos = ((h1 + i * h2) >>> 0) % BLOOM_M;
    const byteIdx = bitPos >>> 3;
    const bitIdx = bitPos & 7;
    if ((bytes[byteIdx]! & (1 << bitIdx)) === 0) return false;
  }
  return true;
}

/**
 * 判断给定域名（含任意层子域名）是否命中广告黑名单。
 * 使用布隆过滤器覆盖 10 万+ 域名，误判率 0.1%。
 */
export function isAdDomain(qname: string | null | undefined): boolean {
  if (!qname) return false;
  const lower = qname.toLowerCase();
  if (bloomCheck(lower)) return true;
  // 检查父域名
  let idx = 0;
  while (idx >= 0) {
    idx = lower.indexOf(".", idx + 1);
    if (idx < 0) break;
    if (bloomCheck(lower.slice(idx + 1))) return true;
  }
  return false;
}
